schema_ddl:
CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_cliente TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL
);

CREATE TABLE portafogli (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    nome_portafoglio TEXT NOT NULL,
    data_creazione TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE investimenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    portafoglio_id INT REFERENCES portafogli(id),
    ticker TEXT NOT NULL,
    quantita NUMERIC(18, 8) NOT NULL CHECK (quantita > 0),
    prezzo_acquisto NUMERIC(19, 4) NOT NULL CHECK (prezzo_acquisto >= 0)
);
